<body>
<header>
  <h1><span class="mk">◆</span>Continuity Board</h1>
  <div class="scenefield">
    <input id="sceneTitle" type="text" placeholder="Scene title — e.g. The Confrontation at the Pier">
  </div>
  <div class="topbtns">
    <button class="btn ghost" id="btnExport">⬇ Save .json</button>
    <button class="btn ghost" id="btnLoad">⬆ Load</button>
    <input id="importer" type="file" accept=".json" style="display:none">
  </div>
</header>

<nav>
  <button class="tab active" data-p="chars">Characters</button>
  <button class="tab" data-p="rels">Relationships</button>
