    <div class="full"><label>Secret / withheld</label><input type="text" id="cSecret"></div>
  </div>
  <div class="dlg-foot">
    <span class="dlg-status" id="charStatus"></span>
    <button class="btn ghost" id="charCancel">Cancel</button>
    <button class="btn primary" id="charSave">Save</button>
