<script>
"use strict";
const KEY='continuity-board-v1';
let state={sceneTitle:'',characters:[],relationships:[],beats:[],facts:[],flags:[],openThreads:''};
const $=id=>document.getElementById(id);
const uid=()=>Math.random().toString(36).slice(2,9);

function load(){try{const r=localStorage.getItem(KEY);if(r)state=Object.assign(state,JSON.parse(r));}catch(e){}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){}}
function nameOf(id){const c=state.characters.find(c=>c.id===id);return c?c.name:'?';}

/* DOM builder: safe by construction — text always via textContent / text nodes */
function el(tag,opts,...kids){
  const n=document.createElement(tag);
  if(opts){
    for(const k in opts){
      const v=opts[k];
      if(v==null||v===false)continue;
      if(k==='class')n.className=v;
      else if(k==='text')n.textContent=v;
      else if(k==='dataset')Object.assign(n.dataset,v);
      else if(k.length>2&&k.slice(0,2)==='on'&&typeof v==='function')n.addEventListener(k.slice(2),v);
      else if(k==='draggable')n.draggable=!!v;
      else n.setAttribute(k,v);
    }
  }
  for(const c of kids){
    if(c==null||c===false)continue;
    n.append(c&&c.nodeType?c:document.createTextNode(String(c)));
  }
  return n;
}
function toast(m){const t=$('toast');t.textContent=m;t.classList.add('show');
  clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('show'),1600);}
function setStatus(id,msg){const s=$(id);if(!s)return;s.textContent=msg||'';
  if(msg){clearTimeout(s._t);s._t=setTimeout(()=>{s.textContent='';},2600);}}

/* inline two-step delete check replacing the blocking browser dialog */
function confirmBtn(onConfirm){
  let armed=false,timer=null;
  const b=el('button',{class:'x',title:'delete',text:'✕'});
  b.addEventListener('click',()=>{
    if(armed){clearTimeout(timer);onConfirm();return;}
    armed=true;b.textContent='confirm ✕';b.classList.add('arm');
    timer=setTimeout(()=>{armed=false;b.textContent='✕';b.classList.remove('arm');},2500);
  });
  return b;
}

