/* ---- beat dialog ---- */
let chipSel=[];
function beatDlg(b){
  $('beatDlgTitle').textContent=b?'Edit beat':'Add beat';
  $('bId').value=b?b.id:'';$('bTitle').value=b?b.title:'';$('bType').value=b?b.type:'Setup';
