function delBeat(id){state.beats=state.beats.filter(b=>b.id!==id);
  state.flags=state.flags.filter(f=>f.beatId!==id);save();render();}

/* ---- fact dialog ---- */
function factDlg(f){
  $('factDlgTitle').textContent=f?'Edit fact':'Add prior fact';
  $('fId').value=f?f.id:'';$('fCat').value=f?f.cat:'Backstory';$('fText').value=f?f.text:'';
  setStatus('factStatus','');$('factDialog').showModal();
}
function saveFact(){
  if(!$('fText').value.trim()){setStatus('factStatus','Fact text required');return;}
