/* ---- builders ---- */
function kv(lab,val,cls){
  return el('div',{class:'kv'},
    el('span',{class:'lab'},lab),
    el('span',cls?{class:cls}:{},val));
}
function charCard(c){
  const head=el('h3',{},c.name,confirmBtn(()=>delChar(c.id)));
  const card=el('div',{class:'card charcard'},head);
  if(c.role)card.append(el('div',{class:'role'},c.role));
  if(c.want)card.append(kv('Wants',c.want,'want'));
  if(c.need)card.append(kv('Needs',c.need,'need'));
  if(c.state)card.append(kv('State now',c.state));
  if(c.secret)card.append(kv('Secret',c.secret,'secret'));
  card.append(el('div',{style:'margin-top:10px'},
    el('button',{class:'btn ghost',onclick:()=>editChar(c.id)},'Edit')));
  return card;
}
function relRow(r){
  const meter=el('div',{class:'meter'},el('i',{style:'width:'+(r.tension*10)+'%'}));
  const row=el('div',{class:'rel'},
    el('div',{class:'pair'},nameOf(r.a),el('span',{class:'arrow'},'↔'),nameOf(r.b)),
    meter,
    el('div',{class:'tval'},r.tension+'/10'),
    el('button',{class:'btn ghost',onclick:()=>editRel(r.id)},'Edit'),
    confirmBtn(()=>delRel(r.id)));
  if(r.nature)row.append(el('div',{class:'relnote'},r.nature));
  return row;
}
function beatRow(b,i){
  const row=el('div',{class:'beat',draggable:true,dataset:{id:b.id},
    ondragstart:e=>{dragId=b.id;row.classList.add('dragging');e.dataTransfer.effectAllowed='move';},
    ondragend:()=>{row.classList.remove('dragging');clearOver();dragId=null;},
    ondragover:e=>{e.preventDefault();clearOver();if(b.id!==dragId)row.classList.add('over');},
    ondrop:e=>{e.preventDefault();
      if(!dragId||dragId===b.id)return;
      const arr=state.beats,from=arr.findIndex(x=>x.id===dragId),to=arr.findIndex(x=>x.id===b.id);
      const m=arr.splice(from,1)[0];arr.splice(to,0,m);save();render();}
  });
  row.append(el('span',{class:'grip'},'⬍'),el('span',{class:'num'},String(i+1)));
  row.append(el('div',{class:'bt'},el('h4',{},b.title),el('span',{class:'tag'},b.type)));
  if(b.shift)row.append(el('div',{class:'shift'},'→ '+b.shift));
  if(b.chars.length){
    const who=el('div',{class:'who'},el('b',{},'In play: '),b.chars.map(id=>nameOf(id)).join(', '));
    row.append(who);
  }
  if(b.notes)row.append(el('div',{class:'nts'},b.notes));
  row.append(el('div',{style:'margin-top:8px;display:flex;gap:8px'},
    el('button',{class:'btn ghost',onclick:()=>editBeat(b.id)},'Edit'),
    confirmBtn(()=>delBeat(b.id))));
  return row;
}
function factRow(f){
  const lock=el('button',{class:'lockbtn'+(f.locked?' on':''),title:f.locked?'locked':'lock',
    onclick:()=>toggleLock(f.id)},f.locked?'🔒':'🔓');
  return el('div',{class:'fact'+(f.locked?' locked':'')},
    lock,
    el('span',{class:'cat'},f.cat),
    el('span',{class:'txt'},f.text),
    el('button',{class:'btn ghost',onclick:()=>editFact(f.id)},'Edit'),
    confirmBtn(()=>delFact(f.id)));
}

/* facts whose text mentions any character present in the beat */
function factsForBeat(b){
  const names=b.chars.map(id=>nameOf(id)).filter(n=>n&&n!=='?');
  const blob=(b.title+' '+b.shift+' '+b.notes).toLowerCase();
  state.characters.forEach(c=>{
    if(c.name&&blob.includes(c.name.toLowerCase())&&!names.includes(c.name))names.push(c.name);
  });
  if(!names.length)return [];
  return state.facts.filter(f=>{
    const t=f.text.toLowerCase();
    return names.some(n=>t.includes(n.toLowerCase()));
  });
}
function checkRow(b,i){
  const box=el('div',{class:'checkbeat'},el('h4',{},(i+1)+'. '+b.title));
  const rel=factsForBeat(b);
  if(rel.length){
    rel.forEach(f=>{
      const rf=el('div',{class:'relfact'+(f.locked?' locked':'')});
      if(f.locked)rf.append('🔒 ');
      rf.append(el('span',{class:'mini'},'['+f.cat+'] '),f.text);
      box.append(rf);
    });
  }else{
    box.append(el('div',{class:'clean'},'No prior facts touch these characters — nothing to reconcile.'));
  }
  state.flags.filter(fl=>fl.beatId===b.id).forEach(fl=>{
    const f=state.facts.find(x=>x.id===fl.factId);if(!f)return;
    box.append(el('div',{class:'flag'},
      el('span',{},el('span',{class:'warnicon'},'⚑ '),'Conflicts with: '+f.text),
      el('button',{class:'x',onclick:()=>delFlag(b.id,fl.factId)},'✕')));
  });
  if(state.facts.length){
    const sel=el('select',{});
    sel.append(el('option',{value:''},'Flag a conflict with a fact…'));
    state.facts.forEach(f=>sel.append(el('option',{value:f.id},f.text.slice(0,60))));
    box.append(el('div',{class:'flagrow'},sel,
      el('button',{class:'btn',onclick:()=>addFlag(b.id,sel)},'⚑ Flag')));
  }
  return box;
}

/* ---- render ---- */
function render(){
  $('sceneTitle').value=state.sceneTitle||'';
  $('openThreads').value=state.openThreads||'';

  const cg=$('charGrid');cg.replaceChildren();
  if(state.characters.length)state.characters.forEach(c=>cg.append(charCard(c)));
  else cg.append(el('div',{class:'empty'},'No characters yet — add the people in this scene.'));

  const rl=$('relList');rl.replaceChildren();
  if(state.relationships.length)state.relationships.forEach(r=>rl.append(relRow(r)));
  else rl.append(el('div',{class:'empty'},'No relationships mapped yet.'));

  const bl=$('beatList');bl.replaceChildren();
  if(state.beats.length)state.beats.forEach((b,i)=>bl.append(beatRow(b,i)));
  else bl.append(el('div',{class:'empty'},"No beats yet — add the scene's moves and drag to sequence."));

  const fl=$('factList');fl.replaceChildren();
  if(state.facts.length)state.facts.forEach(f=>fl.append(factRow(f)));
  else fl.append(el('div',{class:'empty'},"No prior facts logged. Add what's already canon."));

  const ck=$('checkList');ck.replaceChildren();
  if(state.beats.length)state.beats.forEach((b,i)=>ck.append(checkRow(b,i)));
  else ck.append(el('div',{class:'empty'},'Add beats to run the check.'));

  buildHandoff();
  save();
}

/* ---- handoff (plain text via textContent) ---- */
function buildHandoff(){
  const L=[];
  L.push('# SCENE HANDOFF — '+(state.sceneTitle||'(untitled scene)'));
  L.push('');
  L.push('## CHARACTERS IN PLAY');
  if(state.characters.length)state.characters.forEach(c=>{
    L.push('- '+c.name+(c.role?' ('+c.role+')':''));
    if(c.want)L.push('    wants: '+c.want);
    if(c.need)L.push('    needs: '+c.need);
    if(c.state)L.push('    state now: '+c.state);
    if(c.secret)L.push('    secret: '+c.secret);
  });else L.push('- (none)');
  L.push('');
  L.push('## LIVE TENSIONS');
  if(state.relationships.length)state.relationships.slice().sort((a,b)=>b.tension-a.tension)
    .forEach(r=>L.push('- '+nameOf(r.a)+' <-> '+nameOf(r.b)+'  ['+r.tension+'/10]'+(r.nature?'  — '+r.nature:'')));
  else L.push('- (none)');
  L.push('');
  L.push('## BEAT SEQUENCE');
  if(state.beats.length)state.beats.forEach((b,i)=>{
    L.push((i+1)+'. ['+b.type+'] '+b.title);
    if(b.shift)L.push('    shift: '+b.shift);
    if(b.chars.length)L.push('    in play: '+b.chars.map(id=>nameOf(id)).join(', '));
    if(b.notes)L.push('    notes: '+b.notes.replace(/\n/g,' '));
  });else L.push('(none)');
  L.push('');
  const locked=state.facts.filter(f=>f.locked);
  L.push('## LOCKED FACTS (must hold)');
  if(locked.length)locked.forEach(f=>L.push('- ['+f.cat+'] '+f.text));else L.push('- (none locked)');
  const other=state.facts.filter(f=>!f.locked);
  if(other.length){L.push('');L.push('## OTHER ESTABLISHED FACTS');
    other.forEach(f=>L.push('- ['+f.cat+'] '+f.text));}
  if(state.flags.length){L.push('');L.push('## FLAGGED CONFLICTS TO RESOLVE');
    state.flags.forEach(fl=>{const b=state.beats.find(x=>x.id===fl.beatId);
      const f=state.facts.find(x=>x.id===fl.factId);
      if(b&&f)L.push('- Beat "'+b.title+'" vs fact: '+f.text);});}
  L.push('');
  L.push('## OPEN THREADS / NEXT SCENE');
  L.push((state.openThreads||'').trim()||'(none noted)');
  const out=L.join('\n');
  $('handoffOut').textContent=out;
  return out;
}
function copyHandoff(){
  const t=buildHandoff();
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(t).then(()=>toast('Copied'),()=>fallbackCopy(t));
  }else fallbackCopy(t);
}
function fallbackCopy(t){
  const ta=el('textarea',{});ta.value=t;document.body.append(ta);ta.select();
  try{document.execCommand('copy');toast('Copied');}catch(e){toast('Copy failed');}ta.remove();
}
function downloadHandoff(){
  const t=buildHandoff();
  const slug=(state.sceneTitle||'scene').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'scene';
  dl(t,'handoff-'+slug+'.md','text/markdown');
}

/* ---- json ---- */
function exportJSON(){dl(JSON.stringify(state,null,2),'continuity-board.json','application/json');}
function importJSON(e){
  const f=e.target.files[0];if(!f)return;
  const r=new FileReader();
  r.onload=()=>{try{const d=JSON.parse(r.result);
    state=Object.assign({sceneTitle:'',characters:[],relationships:[],beats:[],facts:[],flags:[],openThreads:''},d);
    save();render();toast('Loaded');}catch(err){toast('Invalid file');}};
  r.readAsText(f);e.target.value='';
}
function dl(text,name,type){
  const b=new Blob([text],{type});const u=URL.createObjectURL(b);
  const a=el('a',{href:u,download:name});a.click();
  setTimeout(()=>URL.revokeObjectURL(u),1000);
}

load();render();
</script>
</body>
</html>
